export enum Status {
  Pending = 'PENDING',
  Confirmed = 'CONFIRMED',
}

export function statusLabel(s: Status): string {
  return s === Status.Pending ? 'waiting for approval' : 'confirmed';
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { statusLabel } from '../src/status.ts';

test('PENDING waits for approval', () => assert.equal(statusLabel('PENDING'), 'waiting for approval'));
test('CONFIRMED is confirmed', () => assert.equal(statusLabel('CONFIRMED'), 'confirmed'));

