// A union of string literals is pure type information: Node can erase it, tsc can still check it.
export type Status = 'PENDING' | 'CONFIRMED';

export function statusLabel(s: Status): string {
  return s === 'PENDING' ? 'waiting for approval' : 'confirmed';
}

