export type Booking = { lab: string; seats: number };

// Types are gone at runtime, so the check must use values: typeof, null, property reads.
export function isBooking(x: unknown): x is Booking {
  if (typeof x !== 'object' || x === null) return false;
  const o = x as { lab?: unknown; seats?: unknown };
  return typeof o.lab === 'string' && typeof o.seats === 'number';
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { isBooking } from '../src/guard.ts';

test('a real booking passes', () => assert.equal(isBooking({ lab: 'BE-201', seats: 12 }), true));
test('seats as a string fails', () => assert.equal(isBooking({ lab: 'BE-201', seats: '12' }), false));
test('null fails', () => assert.equal(isBooking(null), false));
test('a string fails', () => assert.equal(isBooking('BE-201'), false));

